import * as THREE from 'three';
import { RotatingObstacle, type RotatingObstacleOptions } from './RotatingObstacle';
import type { ObstacleBodyHandle, ObstacleColliderSpec } from './types';
import { IDENTITY_QUATERNION } from './types';
import { TAU } from './rotation';
import { requireCount, requirePositive } from './validation';

export interface WindmillOptions extends RotatingObstacleOptions {
  bladeCount?: number;
  bladeLength?: number;
  bladeWidth?: number;
  bladeDepth?: number;
  towerHeight?: number;
  towerWidth?: number;
  towerDepth?: number;
  color?: number;
  towerColor?: number;
}

export class Windmill extends RotatingObstacle {
  readonly bladeCount: number;
  readonly bladeLength: number;
  readonly bladeWidth: number;
  readonly bladeDepth: number;
  readonly towerHeight: number;
  readonly towerWidth: number;
  readonly towerDepth: number;
  readonly colliders: readonly ObstacleColliderSpec[];
  readonly staticColliders: readonly ObstacleColliderSpec[];

  private staticBodyHandle?: ObstacleBodyHandle;

  constructor(options: WindmillOptions) {
    super({ ...options, axis: options.axis ?? { x: 0, y: 0, z: 1 } });

    this.bladeCount = requireCount(options.bladeCount ?? 4, 'windmill blade count', 2);
    this.bladeLength = requirePositive(options.bladeLength ?? 2.2, 'windmill blade length');
    this.bladeWidth = requirePositive(options.bladeWidth ?? 0.45, 'windmill blade width');
    this.bladeDepth = requirePositive(options.bladeDepth ?? 0.18, 'windmill blade depth');
    this.towerHeight = requirePositive(options.towerHeight ?? 2.5, 'windmill tower height');
    this.towerWidth = requirePositive(options.towerWidth ?? 0.7, 'windmill tower width');
    this.towerDepth = requirePositive(options.towerDepth ?? 0.7, 'windmill tower depth');

    const bladeMaterial = new THREE.MeshStandardMaterial({ color: options.color ?? 0xf5c542 });
    const towerMaterial = new THREE.MeshStandardMaterial({ color: options.towerColor ?? 0x8d99ae });
    const colliders: ObstacleColliderSpec[] = [];

    for (let index = 0; index < this.bladeCount; index += 1) {
      const angle = (TAU * index) / this.bladeCount;
      const blade = new THREE.Mesh(
        new THREE.BoxGeometry(this.bladeLength, this.bladeWidth, this.bladeDepth),
        bladeMaterial,
      );
      blade.position.set(
        Math.cos(angle) * this.bladeLength / 2,
        Math.sin(angle) * this.bladeLength / 2,
        0,
      );
      blade.rotation.z = angle;
      blade.castShadow = true;
      blade.receiveShadow = true;
      this.pivot.add(blade);

      colliders.push({
        halfExtents: {
          x: this.bladeLength / 2,
          y: this.bladeWidth / 2,
          z: this.bladeDepth / 2,
        },
        offset: {
          x: Math.cos(angle) * this.bladeLength / 2,
          y: Math.sin(angle) * this.bladeLength / 2,
          z: 0,
        },
        rotation: { x: 0, y: 0, z: Math.sin(angle / 2), w: Math.cos(angle / 2) },
      });
    }

    const hub = new THREE.Mesh(
      new THREE.CylinderGeometry(this.bladeWidth * 0.65, this.bladeWidth * 0.65, this.bladeDepth * 1.6, 20),
      bladeMaterial,
    );
    hub.rotation.x = Math.PI / 2;
    hub.castShadow = true;
    this.pivot.add(hub);

    const tower = new THREE.Mesh(
      new THREE.BoxGeometry(this.towerWidth, this.towerHeight, this.towerDepth),
      towerMaterial,
    );
    tower.position.y = -this.towerHeight / 2;
    tower.castShadow = true;
    tower.receiveShadow = true;
    this.root.add(tower);

    this.colliders = colliders;
    this.staticColliders = [{
      halfExtents: {
        x: this.towerWidth / 2,
        y: this.towerHeight / 2,
        z: this.towerDepth / 2,
      },
      offset: { x: 0, y: -this.towerHeight / 2, z: 0 },
    }];

    this.mountBody(this.colliders);
    if (this.physics) {
      this.staticBodyHandle = this.physics.createBody({
        id: `${this.id}:static`,
        kind: 'fixed',
        position: { ...this.position },
        rotation: { ...IDENTITY_QUATERNION },
        colliders: this.staticColliders,
      });
    }
  }

  override dispose(): void {
    if (this.disposed) return;
    this.staticBodyHandle?.dispose();
    this.staticBodyHandle = undefined;
    super.dispose();
  }
}
